(function(root){
 function duplicate(project,ids,mode,gap,newId){
  const source=project.rooms.filter(r=>ids.includes(r.id));if(!source.length)throw Error('Wybierz przynajmniej jedno pomieszczenie.');if(project.rooms.length+source.length>100)throw Error('Maksymalnie 100 pomieszczeń.');if(!['beside','above','below'].includes(mode)||!Number.isFinite(gap)||gap<0||gap>10000)throw Error('Odstęp musi wynosić 0–10000 mm.');
  const xs=source.flatMap(r=>r.points.map(p=>r.x+p.x)),lo=Math.min(...source.map(r=>r.elevation||0)),hi=Math.max(...source.map(r=>(r.elevation||0)+r.h)),dx=mode==='beside'?Math.max(...xs)-Math.min(...xs)+gap:0,dz=mode==='above'?hi-lo+gap:mode==='below'?-(hi-lo+gap):0,map=new Map();
  const rooms=source.map(r=>{const c=JSON.parse(JSON.stringify(r));c.id=newId();map.set(r.id,c.id);c.name=(r.name+' — kopia').slice(0,60);c.x+=dx;c.elevation=(r.elevation||0)+dz;c.elements.forEach(e=>e.id=newId());if(Math.abs(c.x)>200000||Math.abs(c.elevation)>200000)throw Error('Kopia przekracza zakres współrzędnych.');return c;});
  const links=project.links.filter(l=>map.has(l.a)&&map.has(l.b)).map(l=>({...l,id:newId(),a:map.get(l.a),b:map.get(l.b)}));return {rooms,links};
 }
 if(typeof module!=='undefined'){module.exports={duplicate};return;}
 function setElevation(r,value){if(!Number.isFinite(value)||Math.abs(value)>200000)throw Error('Poziom podłogi: od −200000 do 200000 mm.');if((r.elevation||0)!==value){r.elevation=value;data.links=data.links.filter(l=>l.a!==r.id&&l.b!==r.id);}save();}
 function copyDialog(){modal(`<h2>Kopiuj pomieszczenia</h2><form id="copyRoomsForm"><div class="copy-room-list">${data.rooms.map(r=>`<label><input type="checkbox" name="rooms" value="${r.id}" ${r.id===roomId?'checked':''}> ${esc(r.name)} · poziom ${r.elevation||0} mm</label>`).join('')}</div><label>Ustaw kopię<select name="mode"><option value="beside">Obok — w prawo</option><option value="above">Nad — kolejna kondygnacja</option><option value="below">Pod — niższa kondygnacja</option></select></label><label>Odstęp między obrysami / wysokość przerwy między kondygnacjami · mm<input name="gap" type="number" min="0" max="10000" value="300" required></label><p class="muted">Kopia zawiera pomiary, elementy, zdjęcia i uwagi. Poziom podłogi oraz X/Y możesz później zmienić w planie lokalu. Przy kopiowaniu w pionie odstęp dodaje się do wysokości pomieszczeń.</p><div class="dialog-actions"><button type="button" onclick="closeDialog()">Anuluj</button><button class="primary">Utwórz kopię</button></div></form>`);document.getElementById('copyRoomsForm').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),result=duplicate(data,f.getAll('rooms'),f.get('mode'),Number(f.get('gap')),uid);data.rooms.push(...result.rooms);data.links.push(...result.links);roomId=result.rooms[0].id;wall=0;activeElement=null;shapeDraft=null;view='plan';save();closeDialog();render();}catch(err){toast(err.message)}};}
 const button=()=>{const b=document.createElement('button');b.textContent='⧉ Kopiuj';b.type='button';b.onclick=copyDialog;return b;};
 const editor=renderEditor;renderEditor=function(){editor();document.querySelector('.room-summary')?.append(button());};
 const plan=renderPlan;renderPlan=function(){plan();const bar=document.querySelector('.plan-rotation');bar?.append(button());
 const r=room();document.querySelectorAll('#planSvg [data-id]').forEach(g=>{const other=data.rooms.find(r=>r.id===g.dataset.id);if(other&&(other.elevation||0)!==(r.elevation||0))g.style.display='none';});
 const visible=data.rooms.filter(q=>(q.elevation||0)===(r.elevation||0)),bounds=Geom.bounds(visible.flatMap(q=>q.points.map(p=>({x:q.x+p.x,y:q.y+p.y}))));document.getElementById('planSvg')?.setAttribute('viewBox',`${bounds.x-600} ${bounds.y-600} ${bounds.w+1200} ${bounds.d+1200}`);
 const pick=bar?.querySelector('select');if(pick)for(const o of pick.options){const q=data.rooms.find(r=>r.id===o.value);o.textContent=q.name+' · '+(q.elevation||0)+' mm';}
 const details=document.createElement('details');details.className='room-placement';details.innerHTML=`<summary>Położenie: X ${r.x} · Y ${r.y} · poziom podłogi ${r.elevation||0} mm</summary><div>${[['x','X',r.x],['y','Y',r.y],['elevation','Poziom podłogi',r.elevation||0]].map(([k,label,v])=>`<label>${label} · mm<input id="position-${k}" type="number" min="-200000" max="200000" value="${v}"></label>`).join('')}<button id="applyRoomPosition">Ustaw</button></div></details>`;bar?.after(details);
 document.getElementById('applyRoomPosition').onclick=()=>{try{const values=Object.fromEntries(['x','y','elevation'].map(k=>{const field=document.getElementById('position-'+k),n=Number(field.value);if(field.value===''||!Number.isFinite(n)||Math.abs(n)>200000)throw Error('Wpisz współrzędne w zakresie ±200000 mm.');return [k,n]}));if(values.x!==r.x||values.y!==r.y||values.elevation!==(r.elevation||0))data.links=data.links.filter(l=>l.a!==r.id&&l.b!==r.id);Object.assign(r,values);save();render();}catch(e){toast(e.message)}};
 const caption=document.querySelector('.card.plan .card-top .muted');if(caption)caption.textContent=`Rzut poziomu ${r.elevation||0} mm · 3D pokazuje wszystkie poziomy`;
 };
 const scene=open3D;open3D=function(...args){scene(...args);const controls=document.querySelector('.scene-controls');if(!controls)return;const group=document.createElement('div');group.className='level-controls';group.innerHTML=`<select aria-label="Pomieszczenie do ustawienia poziomu">${data.rooms.map(r=>`<option value="${r.id}" ${r.id===roomId?'selected':''}>${esc(r.name)}</option>`).join('')}</select><label>Poziom podłogi · mm<input type="number" aria-label="Poziom podłogi w 3D" min="-200000" max="200000" value="${room().elevation||0}"></label><button>Ustaw poziom</button>`;const select=group.querySelector('select'),input=group.querySelector('input');select.onchange=()=>input.value=data.rooms.find(r=>r.id===select.value).elevation||0;group.querySelector('button').onclick=()=>{try{if(input.value==='')throw Error('Wpisz poziom w mm.');setElevation(data.rooms.find(r=>r.id===select.value),Number(input.value));render();update3D();}catch(e){toast(e.message)}};controls.append(group);};
 if(typeof projectReady!=='undefined'&&projectReady)render();
})(globalThis);
